     bottom, so avoid block values below ~22 or above ~80.
     ------------------------------------------------------------------------- */
  var MOBILE_POSITIONS = [
    /* Raised on 9 Aug for the display-size lead line. On a 390px screen the
       old 340 left only ~280px of measure after padding, and the longest lead
       ("كل بشرة إلها حكاية... وإلها روتينها.") needed about 300. 358 keeps a
       16px breath either side at 390 and still fits a 360px phone. */
    { inline: 50, block: 46, align: "center", width: 358 }, // 1 — empty frame
    { inline: 50, block: 34, align: "center", width: 358 }, // 2 — products falling through centre: sit higher
    { inline: 50, block: 32, align: "center", width: 358 }, // 3 — products mid-frame
    { inline: 50, block: 31, align: "center", width: 358 }, // 4 — products lower
