    darkSceneOpacity:   0.28,
    midSceneOpacity:    0.42,
    brightSceneOpacity: 0.58,
    dimStart: 0.00, dimMid: 0.50, dimEnd: 1.00,
    gradientWidth:  92,   // % of screen width — broad, so it has no visible edge
