      var p = pos[i] || pos[pos.length - 1];
      ch.style.left = p.inline + "%";
      ch.style.top = p.block + "%";
      ch.style.width = "min(88vw, " + p.width + "px)";
      ch.style.textAlign = p.align;
    });

