      var p = pos[i] || pos[pos.length - 1];
      d.style.left = p.inline + "%";
      d.style.top = p.block + "%";
      d.style.setProperty("--dim-w", dim.gradientWidth + "%");
      d.style.setProperty("--dim-h", dim.gradientHeight + "%");
    });
  }

  /* =========================================================================
     STORY — per-frame update. Called from the SAME ScrollTrigger onUpdate as
     the canvas, so the copy can never drift from the footage.
     ========================================================================= */
  function updateChapters(p) {
    var desktop = isDesktopStory();
    var dim = desktop ? DIM_DESKTOP : DIM_MOBILE;
    var mult = desktop ? DESKTOP_DIM_MULTIPLIER : MOBILE_DIM_MULTIPLIER;

    /* How much shade this point in the footage needs: dark -> mid -> bright. */
    var dimBase;
    if (p <= dim.dimMid) {
      dimBase = lerp(dim.darkSceneOpacity, dim.midSceneOpacity, norm(p, dim.dimStart, dim.dimMid));
    } else {
      dimBase = lerp(dim.midSceneOpacity, dim.brightSceneOpacity, norm(p, dim.dimMid, dim.dimEnd));
    }

