      var panelA = (p <= dim.dimMid)
        ? lerp(pc.dark, pc.mid, norm(p, dim.dimStart, dim.dimMid))
        : lerp(pc.mid, pc.bright, norm(p, dim.dimMid, dim.dimEnd));
      root.style.setProperty("--panel-a", panelA.toFixed(3));
      dimBase *= PANEL.haloScale;
    }

