      else if (p <= t.holdEnd) a = 1;                                    // holding
      else if (p < t.exitEnd) a = 1 - norm(p, t.holdEnd, t.exitEnd);     // fading out
      else a = (t.holdEnd >= 1 && t.exitEnd >= 1) ? 1 : 0;               // final chapter stays

