        ch.style.transform = "translate(-50%, calc(-50% + " + rise.toFixed(1) + "px))";
      }

      dimmers[i].style.opacity = (a * dimBase * (mult[i] || 1)).toFixed(3);

      if (a > bestA) { bestA = a; best = i; }
    }

    /* Only the chapter actually being read is exposed to assistive tech and
       allowed to receive focus. */
    if (best !== activeChapter) {
      activeChapter = best;
      for (var j = 0; j < chapters.length; j++) {
        chapters[j].setAttribute("aria-hidden", j === best ? "false" : "true");
      }
      if (ctaEl) ctaEl.tabIndex = (best === chapters.length - 1) ? 0 : -1;
    }

    /* Scroll cue: present before the first scroll, gone by CUE_FADE_END. */
    if (cueEl) {
      var cueA = 1 - norm(p, 0, CUE_FADE_END);
      cueEl.style.opacity = cueA.toFixed(3);
      cueEl.style.visibility = cueA <= 0.01 ? "hidden" : "visible";
    }
  }

  /* =========================================================================
     Canvas rendering — COVER fit (unchanged)
     ========================================================================= */
  function render() {
    var v = cache[activeKey];
    var cw = pin.clientWidth, ch = pin.clientHeight;
    var bg = VARIANTS[activeKey].bg;
    if (!v || !v.loaded || !v.count) {
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, cw, ch);
      return;
    }
    var i = Math.max(0, Math.min(v.count - 1, Math.round(state.p * (v.count - 1))));
    if (i === lastDrawn) return;
    lastDrawn = i;
    var img = v.images[i];
    if (!img || !img.naturalWidth) return;
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cw, ch);
    var scale = Math.max(cw / img.naturalWidth, ch / img.naturalHeight) * COVER_ZOOM;
    var dw = img.naturalWidth * scale;
    var dh = img.naturalHeight * scale;
    var dx = (cw - dw) * FOCUS_X;
    var dy = (ch - dh) * FOCUS_Y;
    ctx.drawImage(img, dx, dy, dw, dh);
  }

  /* The ONE place the scroll progress fans out: frame + story together. */
  function onProgress() {
    render();
    updateChapters(state.p);
  }

  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    var cw = pin.clientWidth, ch = pin.clientHeight;
    canvas.width = Math.round(cw * dpr);
    canvas.height = Math.round(ch * dpr);
    canvas.style.width = cw + "px";
    canvas.style.height = ch + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    lastDrawn = -1;
    render();
  }

  function ensureVariant(key) {
    var v = cache[key];
    if (v && v.promise) return v.promise;
    v = cache[key] = { images: [], count: 0, loaded: false, promise: null };
    var base = VARIANTS[key].base;
    v.promise = fetch(base + "manifest.json", { cache: "force-cache" })
      .then(function (r) {
        if (!r.ok) throw new Error(key + " manifest.json HTTP " + r.status);
        return r.json();
      })
      .then(function (manifest) {
        var frames = manifest.frames || [];
        v.count = frames.length;
        v.images = new Array(v.count);
        var loaded = 0;
        function bump() {
          loaded++;
          if (key === activeKey && pctEl) {
            pctEl.textContent = Math.round((loaded / v.count) * 100) + "%";
          }
        }
        var jobs = frames.map(function (f, idx) {
          return new Promise(function (resolve) {
            var img = new Image();
            img.decoding = "async";
            img.src = base + f.file;
            v.images[idx] = img;
            var done = function () { bump(); resolve(); };
            if (img.decode) {
              img.decode().then(done).catch(function () { img.onload = done; img.onerror = done; });
            } else { img.onload = done; img.onerror = done; }
          });
        });
        return Promise.all(jobs);
      })
      .then(function () { v.loaded = true; });
    return v.promise;
  }

  function switchTo(key) {
    activeKey = key;
    root.style.setProperty("--seq-bg", VARIANTS[key].bg);
    var v = cache[key];
    if (!v || !v.loaded) {
      if (loader) loader.classList.remove("is-hidden");
      if (pctEl) pctEl.textContent = "0%";
    }
    ensureVariant(key).then(function () {
      if (activeKey !== key) return;
      if (loader) loader.classList.add("is-hidden");
      lastDrawn = -1;
      resize();
      applyStoryLayout();          /* the other video = the other composition */
      updateChapters(state.p);     /* keep the reader's place across the switch */
      if (ScrollTriggerRef) ScrollTriggerRef.refresh();
    });
  }

  function loadScript(src) {
    return new Promise(function (resolve, reject) {
      var ex = document.querySelector('script[src="' + src + '"]');
      if (ex) { if (ex.dataset.loaded) return resolve(); ex.addEventListener("load", resolve); ex.addEventListener("error", reject); return; }
      var s = document.createElement("script");
      s.src = src; s.async = false;
      s.onload = function () { s.dataset.loaded = "1"; resolve(); };
      s.onerror = reject;
      document.head.appendChild(s);
    });
  }
  function ensureGSAP() {
    if (window.gsap && window.ScrollTrigger) return Promise.resolve();
    return loadScript(GSAP_URL).then(function () { return loadScript(ST_URL); });
  }

  function startAnimation() {
    var gsap = window.gsap;
    ScrollTriggerRef = window.ScrollTrigger;
    gsap.registerPlugin(ScrollTriggerRef);

    applyStoryLayout();
    resize();
    render();
    updateChapters(0);            /* Chapter 1 is up before any scroll happens */

    /* ---- THE ONE AND ONLY ScrollTrigger ----
       It drives the frame AND the story from the same progress value. Do not
       add a second trigger or a second pin for the chapters. */
    gsap.to(state, {
      p: 1,
      ease: "none",
      scrollTrigger: {
        trigger: root,
        start: "top top",
        end: function () { return "+=" + (window.innerHeight * SCROLL_DISTANCE_VH); },
        pin: pin, pinSpacing: true,
        scrub: SCRUB_SMOOTHING,
        anticipatePin: 1,
        invalidateOnRefresh: true,
        onUpdate: onProgress
      }
    });

    ScrollTriggerRef.addEventListener("refreshInit", resize);

    var t;
    window.addEventListener("resize", function () {
      clearTimeout(t);
      t = setTimeout(function () {
        var want = pickKey();
        if (want !== activeKey) {
          switchTo(want);                 /* switchTo re-applies the layout */
        } else {
          resize();
          applyStoryLayout();
          updateChapters(state.p);        /* progress preserved */
          if (ScrollTriggerRef) ScrollTriggerRef.refresh();
        }
      }, 150);
    });

    if (loader) loader.classList.add("is-hidden");
  }

  function staticFallback() {
    var v = cache[activeKey];
    if (v && v.count) state.p = 1;
    resize(); render();
    applyStoryLayout();
    updateChapters(state.p);
    if (loader) loader.classList.add("is-hidden");
    window.addEventListener("resize", function () {
      var want = pickKey();
      if (want !== activeKey) switchTo(want);
      else { resize(); applyStoryLayout(); updateChapters(state.p); }
    });
  }

  activeKey = pickKey();
  root.style.setProperty("--seq-bg", VARIANTS[activeKey].bg);
  applyStoryLayout();
  updateChapters(0);

  ensureVariant(activeKey)
    .then(ensureGSAP)
    .then(startAnimation)
    .catch(function (err) {
      console.error("[hero-seq] " + (err && err.message ? err.message : err));
      var v = cache[activeKey];
      if (v && v.loaded && v.images[0]) staticFallback();
      else if (pctEl) pctEl.textContent = "Couldn’t load sequence — check the base URLs";
    });

  /* Exposed for the preview page's dev toolbar only. Harmless in production:
     nothing on the live site reads it. */
  window.__LUVIT_HERO__ = {
    state: state,
    chapters: chapters,
    isDesktopStory: isDesktopStory,
    activeChapter: function () { return activeChapter; }
  };
})();
</script>
